import { useEffect, useRef } from "react";
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";

const CUBE_URL = "/ressources/backgrounds/cube-web.glb";
const SECTION_X = [1.45, -1.45, 1.5, -1.5, 1.4, -1.4];
const FACE_ROTATIONS = [
  [0, 0, 0],
  [0, -Math.PI / 2, 0],
  [0, Math.PI, 0],
  [0, Math.PI / 2, 0],
  [Math.PI / 2, 0, 0],
  [-Math.PI / 2, 0, 0],
];
const SECTION_FACE_INDEXES = [4, 1, 2, 3, 0, 5];
const SECTION_ROLLS = [0, Math.PI / 2, Math.PI / 2, Math.PI / 2, Math.PI / 2, Math.PI / 2];

const disposeMaterial = (material) => {
  Object.values(material).forEach((value) => {
    if (value?.isTexture) value.dispose();
  });
  material.dispose();
};

export default function SectionCubeBackground() {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const scroller = document.querySelector(".content");
    if (!canvas || !scroller) return undefined;

    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    const finePointer = window.matchMedia("(hover: hover) and (pointer: fine)");
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(34, 1, 0.1, 100);
    const cubeAnchor = new THREE.Group();
    const clock = new THREE.Clock();
    const pointer = new THREE.Vector2();
    const targetQuaternion = new THREE.Quaternion();
    const sectionQuaternions = SECTION_FACE_INDEXES.map((faceIndex, sectionIndex) => {
      const face = new THREE.Quaternion().setFromEuler(
        new THREE.Euler(...FACE_ROTATIONS[faceIndex])
      );
      const roll = new THREE.Quaternion().setFromAxisAngle(
        new THREE.Vector3(0, 0, 1),
        SECTION_ROLLS[sectionIndex]
      );
      return roll.multiply(face);
    });
    let renderer;
    let cube;
    let frame = 0;
    let disposed = false;
    let scrollTarget = 0;
    let scrollCurrent = 0;
    let scrollStopTimer = 0;
    let transitioning = false;
    let sectionOffsets = [];

    try {
      renderer = new THREE.WebGLRenderer({
        canvas,
        alpha: true,
        antialias: window.devicePixelRatio <= 1.5,
        powerPreference: "high-performance",
      });
    } catch (error) {
      canvas.dataset.unavailable = "true";
      return undefined;
    }

    renderer.setClearColor(0x000000, 0);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;
    scene.add(cubeAnchor);

    scene.add(new THREE.HemisphereLight(0xdde5ff, 0x0d1020, 2.7));
    const keyLight = new THREE.DirectionalLight(0xffffff, 3.7);
    keyLight.position.set(4, 6, 7);
    scene.add(keyLight);
    const rimLight = new THREE.PointLight(0x7890ff, 18, 18);
    rimLight.position.set(-4, 1, 4);
    scene.add(rimLight);

    camera.position.set(0, 0, 8.2);

    const measureSections = () => {
      sectionOffsets = Array.from(document.querySelectorAll("[data-theme-section]"))
        .slice(0, sectionQuaternions.length)
        .map((section) => section.offsetTop);
    };

    const getSectionProgress = () => {
      if (sectionOffsets.length < 2) return 0;
      const position = scroller.scrollTop;

      for (let index = 0; index < sectionOffsets.length - 1; index += 1) {
        const start = sectionOffsets[index];
        const end = sectionOffsets[index + 1];
        if (position <= end) {
          return index + THREE.MathUtils.clamp((position - start) / Math.max(1, end - start), 0, 1);
        }
      }

      return sectionOffsets.length - 1;
    };

    const updateScroll = (event) => {
      scrollTarget = getSectionProgress();
      if (!event) return;

      transitioning = true;
      window.clearTimeout(scrollStopTimer);
      scrollStopTimer = window.setTimeout(() => {
        transitioning = false;
        scrollTarget = Math.round(getSectionProgress());
      }, 140);
    };

    const updatePointer = (event) => {
      if (reducedMotion.matches || !finePointer.matches || event.pointerType === "touch") return;
      pointer.set(
        (event.clientX / window.innerWidth) * 2 - 1,
        -((event.clientY / window.innerHeight) * 2 - 1)
      );
    };

    const resetPointer = () => pointer.set(0, 0);

    const resize = () => {
      const width = Math.max(1, canvas.clientWidth);
      const height = Math.max(1, canvas.clientHeight);
      const mobile = width < 760;
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, mobile ? 1 : 1.5));
      renderer.setSize(width, height, false);
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      measureSections();
      scrollTarget = getSectionProgress();
    };

    const loader = new GLTFLoader();
    loader.setMeshoptDecoder(MeshoptDecoder);
    loader.load(
      CUBE_URL,
      (gltf) => {
        if (disposed) return;
        cube = gltf.scene;
        const bounds = new THREE.Box3().setFromObject(cube);
        const size = bounds.getSize(new THREE.Vector3());
        const center = bounds.getCenter(new THREE.Vector3());
        const scale = 3.35 / Math.max(size.x, size.y, size.z);

        cube.position.sub(center);
        cube.scale.setScalar(scale);
        cube.traverse((child) => {
          if (!child.isMesh) return;
          child.frustumCulled = true;
          child.castShadow = false;
          child.receiveShadow = false;
        });
        cubeAnchor.add(cube);
        canvas.classList.add("section-cube-background--ready");
      },
      undefined,
      () => {
        if (!disposed) canvas.classList.add("section-cube-background--error");
      }
    );

    const render = () => {
      const delta = Math.min(clock.getDelta(), 0.05);
      scrollCurrent = THREE.MathUtils.damp(scrollCurrent, scrollTarget, 4.5, delta);
      const faceProgress = Math.min(sectionQuaternions.length - 1, scrollCurrent);
      const before = Math.floor(faceProgress);
      const after = Math.min(sectionQuaternions.length - 1, before + 1);
      const blend = THREE.MathUtils.smoothstep(faceProgress - before, 0, 1);
      const horizontal = THREE.MathUtils.lerp(SECTION_X[before], SECTION_X[after], blend);
      const mobile = window.innerWidth < 760;
      canvas.classList.toggle("section-cube-background--foreground", transitioning);

      targetQuaternion.copy(sectionQuaternions[before]).slerp(sectionQuaternions[after], blend);
      cubeAnchor.quaternion.slerp(
        targetQuaternion,
        reducedMotion.matches ? 1 : 1 - Math.exp(-delta * 7)
      );
      cubeAnchor.position.x = THREE.MathUtils.damp(
        cubeAnchor.position.x,
        (transitioning ? 0 : horizontal * (mobile ? 0.72 : 1)) + pointer.x * 0.16,
        4,
        delta
      );
      cubeAnchor.position.y = THREE.MathUtils.damp(
        cubeAnchor.position.y,
        (reducedMotion.matches ? 0 : Math.sin(clock.elapsedTime * 0.55) * 0.1) + pointer.y * 0.12,
        4,
        delta
      );
      const targetScale = (mobile ? 0.76 : 1) * (transitioning ? 1.14 : 1);
      const smoothedScale = THREE.MathUtils.damp(cubeAnchor.scale.x, targetScale, 4, delta);
      cubeAnchor.scale.setScalar(smoothedScale);

      camera.position.x = THREE.MathUtils.damp(camera.position.x, pointer.x * 0.13, 4, delta);
      camera.position.y = THREE.MathUtils.damp(camera.position.y, pointer.y * 0.08, 4, delta);
      camera.lookAt(0, 0, 0);
      renderer.render(scene, camera);
      frame = window.requestAnimationFrame(render);
    };

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(canvas);
    scroller.addEventListener("scroll", updateScroll, { passive: true });
    window.addEventListener("pointermove", updatePointer, { passive: true });
    window.addEventListener("blur", resetPointer);
    finePointer.addEventListener("change", resetPointer);
    reducedMotion.addEventListener("change", resetPointer);
    resize();
    updateScroll();
    render();

    return () => {
      disposed = true;
      window.cancelAnimationFrame(frame);
      window.clearTimeout(scrollStopTimer);
      resizeObserver.disconnect();
      scroller.removeEventListener("scroll", updateScroll);
      window.removeEventListener("pointermove", updatePointer);
      window.removeEventListener("blur", resetPointer);
      finePointer.removeEventListener("change", resetPointer);
      reducedMotion.removeEventListener("change", resetPointer);
      cube?.traverse((child) => {
        if (!child.isMesh) return;
        child.geometry?.dispose();
        if (Array.isArray(child.material)) child.material.forEach(disposeMaterial);
        else if (child.material) disposeMaterial(child.material);
      });
      renderer.dispose();
    };
  }, []);

  return <canvas className="section-cube-background" ref={canvasRef} aria-hidden="true" />;
}
