import { useEffect, useRef } from "react";
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import "./AboutShield.css";

const SHIELD_URL = "/ressources/models/bouclier.glb";

const disposeMaterial = (material) => {
  Object.values(material).forEach((value) => {
    if (value?.isTexture) value.dispose();
  });
  material.dispose();
};

export default function AboutShield() {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return undefined;

    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(32, 1, 0.1, 100);
    const anchor = new THREE.Group();
    const clock = new THREE.Clock();
    let renderer;
    let shield;
    let frame = 0;
    let visible = false;
    let disposed = false;

    try {
      renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true });
    } catch (error) {
      canvas.dataset.unavailable = "true";
      return undefined;
    }

    renderer.setClearColor(0x000000, 0);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    camera.position.set(0, 0, 5.2);
    scene.add(anchor);

    scene.add(new THREE.HemisphereLight(0xe8edff, 0x151527, 2.8));
    const keyLight = new THREE.DirectionalLight(0xffffff, 4.5);
    keyLight.position.set(3, 4, 5);
    scene.add(keyLight);
    const blueLight = new THREE.PointLight(0x657dff, 16, 12);
    blueLight.position.set(-3, 0, 4);
    scene.add(blueLight);

    const resize = () => {
      const width = Math.max(1, canvas.clientWidth);
      const height = Math.max(1, canvas.clientHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5));
      renderer.setSize(width, height, false);
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
    };

    const loader = new GLTFLoader();
    loader.load(
      SHIELD_URL,
      (gltf) => {
        if (disposed) return;
        shield = gltf.scene;
        const bounds = new THREE.Box3().setFromObject(shield);
        const size = bounds.getSize(new THREE.Vector3());
        const center = bounds.getCenter(new THREE.Vector3());
        const scale = 2.8 / Math.max(size.x, size.y, size.z);

        shield.position.sub(center);
        shield.scale.setScalar(scale);
        // Blender exported the shield in the XZ plane. Face it toward the camera,
        // then rotate it 180 degrees in screen space so its top points upward.
        shield.quaternion.setFromAxisAngle(new THREE.Vector3(1, 0, 0), Math.PI / 2);
        shield.quaternion.premultiply(
          new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 0, 1), Math.PI)
        );
        shield.traverse((child) => {
          if (!child.isMesh) return;
          child.castShadow = false;
          child.receiveShadow = false;
        });
        anchor.add(shield);
        canvas.classList.add("about-shield__canvas--ready");
      },
      undefined,
      () => {
        if (!disposed) canvas.classList.add("about-shield__canvas--error");
      }
    );

    const render = () => {
      const elapsed = clock.getElapsedTime();
      if (visible) {
        anchor.rotation.y = reducedMotion.matches ? 0 : Math.sin(elapsed * 0.7) * 0.28;
        anchor.position.y = reducedMotion.matches ? 0 : Math.sin(elapsed * 1.1) * 0.08;
        renderer.render(scene, camera);
      }
      frame = window.requestAnimationFrame(render);
    };

    const resizeObserver = new ResizeObserver(resize);
    const visibilityObserver = new IntersectionObserver(
      ([entry]) => {
        visible = entry.isIntersecting;
      },
      { threshold: 0.05 }
    );
    resizeObserver.observe(canvas);
    visibilityObserver.observe(canvas);
    resize();
    render();

    return () => {
      disposed = true;
      window.cancelAnimationFrame(frame);
      resizeObserver.disconnect();
      visibilityObserver.disconnect();
      shield?.traverse((child) => {
        if (!child.isMesh) return;
        child.geometry?.dispose();
        if (Array.isArray(child.material)) child.material.forEach(disposeMaterial);
        else if (child.material) disposeMaterial(child.material);
      });
      renderer.dispose();
    };
  }, []);

  return (
    <div className="about-shield" role="img" aria-label="Bouclier 3D animé">
      <canvas className="about-shield__canvas" ref={canvasRef} aria-hidden="true" />
    </div>
  );
}
